using System.Net.Http.Json; using System.Security.Cryptography; using System.Text; using System.Text.Json; using System.Text.RegularExpressions; using HabitFlow.Domain; using HabitFlow.Shared; using Microsoft.Extensions.Configuration; using Microsoft.Extensions.Logging;
namespace HabitFlow.Application;
public record LoginDto(string Email,string Password); public record RegisterDto(string Name,string Email,string Password); public record HabitDto(Guid Id,string Name,string Color,string? Category,bool DoneToday,bool IsArchived); public record DashboardDto(string Name,int ActiveHabits,int DoneToday,int DayPercent,int BestStreak,IReadOnlyList<HabitDto> Habits); public record ProgressDto(int TotalHabits,int TotalCompletions,int BestStreak,int Rate7Days,int Rate30Days); public record WhatsAppOptions(bool Enabled,string? Number,string? DefaultMessage,string? ButtonText);
public interface IPasswordHasher{string Hash(string password); bool Verify(string password,string hash);} public sealed class BCryptPasswordHasher:IPasswordHasher{public string Hash(string password)=>BCrypt.Net.BCrypt.HashPassword(password); public bool Verify(string password,string hash)=>BCrypt.Net.BCrypt.Verify(password,hash);} 
public sealed class ProtocolGenerator{public string Generate(string prefix="HF")=>$"{prefix}-{DateTime.UtcNow:yyyyMMdd}-{RandomNumberGenerator.GetInt32(100000,999999)}";} public sealed class AdminAuthorizationService{public Result EnsureAdmin(User user)=>user.Role==UserRole.Admin?Result.Success():Result.Failure("admin.forbidden","Acesso administrativo negado.");}
public sealed class HabitPolicy{public Result CanCreate(User user,int active)=>DomainPolicies.CanCreateHabit(user,active)?Result.Success():Result.Failure("plan.free_limit","Plano gratuito limitado a 5 hábitos ativos.");}
public sealed class ProgressService{public int CurrentStreak(IEnumerable<DateOnly> dates,DateOnly today){var set=dates.ToHashSet();var streak=0;for(var d=today;set.Contains(d);d=d.AddDays(-1))streak++;return streak;} public int BestStreak(IEnumerable<DateOnly> dates){var ordered=dates.Distinct().Order().ToList();var best=0;var cur=0;DateOnly? prev=null;foreach(var d in ordered){cur=prev.HasValue&&d==prev.Value.AddDays(1)?cur+1:1;best=Math.Max(best,cur);prev=d;}return best;} public Result<ProgressDto> Build(IReadOnlyList<Habit> habits,IReadOnlyList<HabitCompletion> completions){var best=BestStreak(completions.Select(x=>x.CompletedDate));return Result<ProgressDto>.Success(new(habits.Count,completions.Count,best,0,0));}}
public sealed class LogSanitizer{static readonly Regex Secret=new("(?i)(password|senha|token|cookie|secret|authorization)\\s*[:=]\\s*([^,;&\\s]+)",RegexOptions.Compiled); public string Sanitize(string? input)=>string.IsNullOrWhiteSpace(input)?string.Empty:Secret.Replace(input,"$1=***"); public string SanitizeJson(object metadata)=>Sanitize(JsonSerializer.Serialize(metadata));}
public sealed class WhatsAppValidator{static readonly Regex Phone=new(@"^\+?[1-9]\d{10,14}$",RegexOptions.Compiled); static readonly Regex Html=new("<\\s*script|<[^>]+>",RegexOptions.IgnoreCase|RegexOptions.Compiled); public Result Validate(WhatsAppOptions o){if(!o.Enabled)return Result.Success(); if(!Phone.IsMatch(o.Number??""))return Result.Failure("whatsapp.number","Número inválido."); if(Html.IsMatch(o.DefaultMessage??"")||Html.IsMatch(o.ButtonText??""))return Result.Failure("whatsapp.html","HTML não é permitido."); return Result.Success();}}
public sealed class AuditService(IAuditRepository repo,LogSanitizer sanitizer){public Task LogAsync(string action,string message,AuditSeverity severity=AuditSeverity.Info,Guid? userId=null,string? email=null,object? metadata=null,CancellationToken ct=default)=>repo.AddSystemAsync(new(Guid.NewGuid(),userId,email,severity,"web",action,sanitizer.Sanitize(message),metadata is null?null:sanitizer.SanitizeJson(metadata),null,null,DateTime.UtcNow,false),ct);} 
public sealed class AdminAuditService(IAdminAuditRepository repo){public Task LogAsync(User admin,string action,string? reason,Guid? targetId=null,string? targetEmail=null,CancellationToken ct=default)=>repo.AddAsync(new(Guid.NewGuid(),admin.Id,admin.Email,action,targetId,targetEmail,reason,null,DateTime.UtcNow),ct);} 
public sealed class TelegramService(HttpClient http,IConfiguration cfg){public async Task<Result> SendAsync(AuditSeverity severity,string text,CancellationToken ct=default){if(!cfg.GetValue<bool>("Telegram:Enabled"))return Result.Success();var token=cfg["Telegram:BotToken"];var chat=cfg["Telegram:AdminChatId"];if(string.IsNullOrWhiteSpace(token)||string.IsNullOrWhiteSpace(chat))return Result.Failure("telegram.config","Telegram não configurado.");var res=await http.PostAsJsonAsync($"https://api.telegram.org/bot{token}/sendMessage",new{chat_id=chat,text=$"[{severity}] {text}"},ct);return res.IsSuccessStatusCode?Result.Success():Result.Failure("telegram.send","Falha ao enviar Telegram.");}}
public sealed class AuthService(IUserRepository users,IPasswordHasher hasher,AuditService audit){public async Task<Result<User>> RegisterAsync(RegisterDto dto,CancellationToken ct=default){if(dto.Password.Length<8)return Result<User>.Failure("password.short","Senha deve ter ao menos 8 caracteres."); if(await users.GetByEmailAsync(dto.Email,ct) is not null)return Result<User>.Failure("email.exists","E-mail já cadastrado.");var now=DateTime.UtcNow;var user=new User(Guid.NewGuid(),dto.Name,dto.Email.ToLowerInvariant(),hasher.Hash(dto.Password),null,UserRole.User,AccountStatus.Active,RiskStatus.Normal,UserPlan.Free,PlanStatus.Active,false,false,now,now,null,null,now,now);await users.CreateAsync(user,ct);await audit.LogAsync("user_registered","Novo usuário",AuditSeverity.Info,user.Id,user.Email,null,ct);return Result<User>.Success(user);} public async Task<Result<User>> LoginAsync(LoginDto dto,string? ip,string? ua,CancellationToken ct=default){var user=await users.GetByEmailAsync(dto.Email.ToLowerInvariant(),ct);var ok=user is not null&&hasher.Verify(dto.Password,user.PasswordHash);await users.AddLoginAttemptAsync(new(Guid.NewGuid(),dto.Email,ok,ip,ua,DateTime.UtcNow),ct);await audit.LogAsync(ok?"login_success":"login_failed","Tentativa de login",ok?AuditSeverity.Info:AuditSeverity.Warning,user?.Id,user?.Email,null,ct);return ok?Result<User>.Success(user!):Result<User>.Failure("login.invalid","E-mail ou senha inválidos.");}}
public sealed class UserService(IUserRepository repo){public Task<User?> GetAsync(Guid id,CancellationToken ct=default)=>repo.GetByIdAsync(id,ct); public Task<IReadOnlyList<User>> SearchAsync(string? q,CancellationToken ct=default)=>repo.SearchAsync(q,ct);} 
public sealed class HabitService(IHabitRepository habits,IHabitCompletionRepository completions,HabitPolicy policy,AuditService audit){public async Task<Result<Habit>> CreateAsync(User user,string name,string color,string? category,CancellationToken ct=default){var active=await habits.CountActiveByUserAsync(user.Id,ct);var can=policy.CanCreate(user,active);if(can.IsFailure)return Result<Habit>.Failure(can.Error.Code,can.Error.Message);var now=DateTime.UtcNow;var h=new Habit(Guid.NewGuid(),user.Id,name,color,category,false,null,now,now);await habits.CreateAsync(h,ct);await audit.LogAsync("habit_created","Hábito criado",AuditSeverity.Info,user.Id,user.Email,new{name},ct);return Result<Habit>.Success(h);} public Task<IReadOnlyList<Habit>> ListAsync(Guid userId,CancellationToken ct=default)=>habits.ListByUserAsync(userId,ct); public Task MarkTodayAsync(User user,Guid habitId,CancellationToken ct=default)=>completions.AddAsync(new(Guid.NewGuid(),habitId,user.Id,DateOnly.FromDateTime(DateTime.UtcNow),DateTime.UtcNow),ct); public Task UnmarkTodayAsync(Guid habitId,CancellationToken ct=default)=>completions.DeleteAsync(habitId,DateOnly.FromDateTime(DateTime.UtcNow),ct);} 
public sealed class ProfileService(IUserRepository users){public Task<User?> GetAsync(Guid id,CancellationToken ct=default)=>users.GetByIdAsync(id,ct);} public sealed class SupportService(ISupportRepository repo,ProtocolGenerator gen){public Task CreateTicketAsync(User user,string title,string description,CancellationToken ct=default)=>repo.CreateTicketAsync(new(Guid.NewGuid(),user.Id,gen.Generate("SUP"),"General",TicketStatus.Open,"Normal",title,description,"web",DateTime.UtcNow,DateTime.UtcNow,null),ct);} public sealed class AdminService(UserService users,AdminAuthorizationService auth){public async Task<Result<IReadOnlyList<User>>> SearchUsersAsync(User admin,string? q,CancellationToken ct=default){var r=auth.EnsureAdmin(admin);return r.IsFailure?Result<IReadOnlyList<User>>.Failure(r.Error.Code,r.Error.Message):Result<IReadOnlyList<User>>.Success(await users.SearchAsync(q,ct));}} public sealed class SettingsService(ISettingsRepository repo){public Task<IReadOnlyList<SystemSetting>> ListAsync(CancellationToken ct=default)=>repo.ListAsync(ct);} public sealed class WhatsAppService(WhatsAppValidator validator){public Result Validate(WhatsAppOptions options)=>validator.Validate(options);} public sealed class LgpdService(ILgpdRepository repo,ProtocolGenerator gen){public Task RequestAsync(User user,LgpdRequestType type,CancellationToken ct=default)=>repo.CreateAsync(new(Guid.NewGuid(),user.Id,gen.Generate("LGPD"),type,LgpdRequestStatus.Requested,null,null,null,DateTime.UtcNow,DateTime.UtcNow,null),ct);} public sealed class BillingService(IBillingRepository repo){public Task AddAsync(BillingEvent e,CancellationToken ct=default)=>repo.AddAsync(e,ct);} 
